const languageIndex = Object.freeze({ en: 1, es: 2, fr: 3, "pt-BR": 4 });

export const dailyWorkflowLanguage = Object.freeze(
  Object.fromEntries(
    Object.entries(languageIndex).map(([language, index]) => [
      language,
      Object.freeze(Object.fromEntries(rows.map(([key, ...copy]) => [key, copy[index - 1]]))),
    ])
  )
);

export const DAILY_WORKFLOW_KEYS = Object.freeze(rows.map(([key]) => key));
